static void arena(void){headless=1;pilotConfigured=0;game_reset();g.mode=1;g.fx=0;g.wave=3;ex.section=1;ex.phase=ex.oldPhase=mission_phase(3);ex.intro=ex.travel=ex.entryY=0;ex.rearSpawned=1;g.clock=-100000;environment_enter();player_y=230*Q;g.px=160*Q;terrain.lastShipX=160;terrain.lastShipY=230;}
int main(void){headless=1;int contexts[4][2]={{3,1},{3,3},{6,1},{6,6}},failed=0,cases=0;for(int c=0;c<4;c++)for(int ship=0;ship<3;ship++)for(int rank=1;rank<=4;rank+=3)for(int empty=0;empty<2;empty++){selectedShip=ship;memset(starterVariants,0,sizeof(starterVariants));starterVariants[0]=3;arena();g.weapon=0;g.weaponLevel[0]=rank;g.wave=contexts[c][0];ex.section=contexts[c][1];ex.phase=ex.oldPhase=mission_phase(g.wave);g.clock=0;environment_enter();g.px=160*Q;player_y=230*Q;terrain.lastShipX=160;terrain.lastShipY=230;if(empty){g.weaponEnergy[0]=0;g.weaponHeat[0]=300;}int section=ex.section,frames=0,cutters=0,maxEnemies=0,started=g.lives;for(int t=0;t<7500&&ex.section==section&&g.mode==1;t++){game_step(4,0);frames=t+1;cutters+=ex.env.cutter;if(enemy_count()>maxEnemies)maxEnemies=enemy_count();}int ok=ex.section==section+1&&g.mode==1&&g.lives>0;failed+=!ok;cases++;printf("ORB87 ROUTE m%d s%d ship%d rank%d empty%d time%.2f lives%d/%d bank%d cutter%d NPCmax%d pass%d\n",contexts[c][0],section,ship,rank,empty,frames/50.,g.lives,started,g.weaponEnergy[0],cutters,maxEnemies,ok);}printf("RESULT Orb87 routecases%d failures%d depth%d\n",cases,failed,TERRAIN_H);return failed?1:0;}
